function OVERLAP-DEFECT(P, Q):
    require length(P) = length(Q) = n
    shared <- 0
    for t <- 1 to n:
        shared <- shared + min(P[t], Q[t])
    return 1 - shared

// Invariant: for probability vectors P, Q,
//     OVERLAP-DEFECT(P, Q) = (1/2) * sum_t |P[t] - Q[t]|
//                          = total variation distance of P and Q,
// and 0 <= OVERLAP-DEFECT(P, Q) <= 1, with equality to 0 iff P = Q.

function ANALOGY-DISTANCE(M, N):
    // Step 1: atomic types
    for each world s: type_M[s] <- vector of atomic values of M at s
    for each world t: type_N[t] <- vector of atomic values of N at t
    C_M <- partition of worlds by type_M;  C_N <- partition by type_N
    if the multisets of (type, class size) differ:
        return (1, none)                    // no atom-preserving renaming exists

    // Step 2: enumerate type-respecting bijections
    best <- +infinity;  witness <- none
    for each tuple (sigma_k) of permutations, one per type class k:
        assemble f from the sigma_k
        // Step 3: score
        c <- 0
        for each world s:
            row  <- ( N[f(s)][f(t)] : t ranges over worlds )
            c    <- max(c, OVERLAP-DEFECT(M[s], row))
        if c < best: best <- c; witness <- f

    return (best, witness)

// Guarantee: best = d(M, N) and witness underlies an honest
// best-approximate structural analogy; best = 0 iff M and N are isomorphic.

